// ─── File: src/main/java/com/bank/fraud/service/FraudScanService.java ───
package com.bank.fraud.service;

import com.bank.fraud.dto.FraudReport;
import com.bank.fraud.dto.FraudReport.SuspiciousTxn;
import com.bank.fraud.model.Transaction;
import com.bank.fraud.repository.TransactionRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;

@Service
@RequiredArgsConstructor
@Slf4j
public class FraudScanService {

    private final TransactionRepository txnRepo;

    @Value("${fraud.suspicious-amount:1000000}")
    private BigDecimal suspiciousAmount;

    @Value("${fraud.high-risk-countries:NIGERIA,CAYMAN,PANAMA}")
    private String highRiskCountriesCsv;

    // ═══ DEMO 1: PULL-BASED — findFirst short-circuits ═══
    @Transactional(readOnly = true)
    public FraudReport findFirstSuspicious(String accountId) {
        List<Transaction> allTxns = txnRepo.findByAccountId(accountId);
        Set<String> riskCountries = Set.of(highRiskCountriesCsv.split(","));

        AtomicInteger pullCount = new AtomicInteger(0);

        // Pull-based: terminal (findFirst) pulls ONE element at a time
        // When first match found → STOPS! Remaining elements NEVER pulled.
        Optional<SuspiciousTxn> first = allTxns.stream()
            .peek(t -> {
                int n = pullCount.incrementAndGet();
                log.info("  [PULL #{}] Source yields: {} (Rs.{}, {})",
                    n, t.getTxnId(), t.getAmount(), t.getCountry());
            })
            .filter(t -> {
                boolean match = t.isSuspiciousAmount(suspiciousAmount)
                    || t.isHighRiskCountry(riskCountries);
                log.info("  [FILTER] {} → {}", t.getTxnId(), match ? "PASS (Recommended) " : "DROP (Avoid) ");
                return match;
            })
            .map(t -> {
                log.info("  [MAP] {} → creating SuspiciousTxn DTO", t.getTxnId());
                return new SuspiciousTxn(t.getTxnId(), t.getAccountId(), t.getAmount(),
                    t.getCountry(), t.getMerchant(), "Amount > Rs.10L or high-risk country");
            })
            .findFirst();  // SHORT-CIRCUIT: stops after first match!

        log.info("═══ RESULT: Processed {}/{} elements. findFirst stopped early! ═══",
            pullCount.get(), allTxns.size());

        String alertId = generateAlertId();
        return new FraudReport(alertId, "FIND_FIRST (short-circuit)",
            pullCount.get(), allTxns.size(),
            "Pulled " + pullCount.get() + " of " + allTxns.size()
                + " — stream stopped after first match!",
            first.map(List::of).orElse(List.of()));
    }

    // ═══ DEMO 2: FUSION — filter+map+collect in ONE pass ═══
    @Transactional(readOnly = true)
    public FraudReport scanAllSuspicious(String accountId) {
        List<Transaction> allTxns = txnRepo.findByAccountId(accountId);
        Set<String> riskCountries = Set.of(highRiskCountriesCsv.split(","));

        AtomicInteger passNumber = new AtomicInteger(0);

        // FUSION: filter + map + collect happen in ONE pass
        // Each element goes through ALL ops before the next element is pulled
        List<SuspiciousTxn> flagged = allTxns.stream()
            .peek(t -> log.info("  [PASS {}] Processing {} — filter→map→collect on SAME element",
                passNumber.incrementAndGet(), t.getTxnId()))
            .filter(t -> t.isSuspiciousAmount(suspiciousAmount)
                || t.isHighRiskCountry(riskCountries))
            .map(t -> new SuspiciousTxn(t.getTxnId(), t.getAccountId(), t.getAmount(),
                t.getCountry(), t.getMerchant(),
                t.isSuspiciousAmount(suspiciousAmount) ? "High amount" : "High-risk country"))
            .toList();

        log.info("═══ FUSION: {} elements, ONE pass, not 3 separate loops ═══", allTxns.size());

        return new FraudReport(generateAlertId(), "FULL_SCAN (fused)",
            allTxns.size(), allTxns.size(),
            "Single pass through " + allTxns.size() + " elements — filter+map+collect fused!",
            flagged);
    }

    // ═══ DEMO 3: INFINITE STREAM — only possible because no storage ═══
    public FraudReport demonstrateInfiniteStream() {
        // This stream has NO size — it generates alert IDs forever!
        // Only possible because stream stores NOTHING.
        List<String> alertIds = Stream.generate(this::generateAlertId)  // infinite!
            .distinct()       // stateful — but stream is infinite, so it keeps pulling
            .limit(5)         // short-circuit: stop after 5 unique IDs
            .toList();

        log.info("═══ INFINITE: Generated {} unique alert IDs from infinite stream ═══",
            alertIds.size());

        return new FraudReport(alertIds.get(0), "INFINITE_STREAM",
            5, Integer.MAX_VALUE,
            "Pulled 5 elements from an INFINITE source — possible because stream stores nothing!",
            List.of());
    }

    private String generateAlertId() {
        return "ALERT-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
    }
}
