// ─── File: src/test/java/com/bank/fraud/service/PullBasedPipelineTest.java ───
package com.bank.fraud.service;

import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class PullBasedPipelineTest {

    @Test
    void pullBasedStopsAfterFirstMatch() {
        List<String> processed = new ArrayList<>();

        Optional<String> first = List.of("TXN-001", "TXN-002", "TXN-003", "TXN-004").stream()
            .peek(t -> processed.add("pulled:" + t))
            .filter(t -> t.equals("TXN-002"))
            .peek(t -> processed.add("matched:" + t))
            .findFirst();

        assertThat(first).contains("TXN-002");
        // Only TXN-001 and TXN-002 were pulled — TXN-003, TXN-004 never touched!
        assertThat(processed).containsExactly("pulled:TXN-001", "pulled:TXN-002", "matched:TXN-002");
    }

    @Test
    void fusionProcessesOneElementAtATime() {
        List<String> log = new ArrayList<>();

        List.of("A", "B", "C").stream()
            .peek(s -> log.add("filter:" + s))
            .filter(s -> !s.equals("B"))
            .peek(s -> log.add("map:" + s))
            .map(String::toLowerCase)
            .toList();

        // FUSED: filter→map on each element before moving to next
        // NOT: filter all → then map all
        assertThat(log).containsExactly(
            "filter:A", "map:A",     // A processed completely
            "filter:B",              // B filtered OUT — no map
            "filter:C", "map:C"      // C processed completely
        );
    }

    @Test
    void streamStoresNothing() {
        // Stream has no size(), no get(index), no contains()
        Stream<String> stream = Stream.of("RELIANCE", "TCS", "HDFC");
        // Cannot: stream.size()    — no such method
        // Cannot: stream.get(0)    — no such method
        // Cannot: stream.contains("TCS") — no such method
        // Can only: terminal operations
        assertThat(stream.count()).isEqualTo(3);
    }

    @Test
    void infiniteStreamWithLimit() {
        // Infinite source — only possible because stream stores nothing
        List<Integer> first5 = Stream.iterate(1, n -> n + 1)  // 1, 2, 3, 4, 5, ...∞
            .limit(5)                                          // short-circuit: stop at 5
            .toList();

        assertThat(first5).containsExactly(1, 2, 3, 4, 5);
        // Without limit → infinite loop → OutOfMemoryError
    }

    @Test
    void statefulOpBuffersButStatelessDoesNot() {
        List<String> log = new ArrayList<>();

        // sorted() is STATEFUL — must see ALL elements before sorting
        List.of("C", "A", "B").stream()
            .peek(s -> log.add("before-sort:" + s))
            .sorted()
            .peek(s -> log.add("after-sort:" + s))
            .toList();

        // Before sort: all 3 pulled (buffered)
        // After sort: emitted in sorted order
        assertThat(log).containsExactly(
            "before-sort:C", "before-sort:A", "before-sort:B",  // ALL pulled before sort
            "after-sort:A", "after-sort:B", "after-sort:C"      // emitted in order
        );
    }
}
